import { useEffect, useState } from 'react'
import { api, ApiError } from '../api'

export type Listing = {
  id: number; symbol: string; name: string; category: string; source: 'local' | 'binance'
  board: 'spot' | 'perp' | 'both'; price: number; launchAt: string
  status: 'scheduled' | 'live' | 'cancelled'; issue?: string
}
export type ListingFeed = { items: Listing[]; serverTime: number }
export type Sentiment = { up: number; flat: number; down: number; updated: string
  fearGreed?: { current: number; yesterday: number; lastWeek: number; bearish: number; bullish: number; updated: string } }

export function useListings(admin = false) {
  const [feed, setFeed] = useState<ListingFeed>()
  const [offset, setOffset] = useState(0)
  const [error, setError] = useState('')
  const endpoint = admin ? '/admin/listings' : '/listings'
  const reload = async () => {
    try {
      const result = await api<ListingFeed>(endpoint)
      setFeed(result)
      setOffset(result.serverTime - Date.now())
      setError('')
    } catch (e) { setError(e instanceof ApiError ? e.code : 'service_unavailable') }
  }
  useEffect(() => {
    void reload()
    const timer = setInterval(reload, 4000)
    return () => clearInterval(timer)
    // Reload is scoped to the selected endpoint.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [endpoint])
  return { items: feed?.items ?? [], offset, error, ready: !!feed, reload }
}

export function remaining(launchAt: string, now: number) {
  let seconds = Math.max(0, Math.ceil((new Date(launchAt).getTime() - now) / 1000))
  const days = Math.floor(seconds / 86400)
  seconds %= 86400
  const clock = [Math.floor(seconds / 3600), Math.floor(seconds % 3600 / 60), seconds % 60]
    .map(v => String(v).padStart(2, '0')).join(':')
  return { days, clock, due: days === 0 && seconds === 0 }
}
